package net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfig;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueobject.TimeoutVO;

class TimeoutValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of timeout of smtp outbound config")
  void test_timeout_value_holder_assign_plain_value() {
    Object holder = new Object();
    TimeoutValueHolder<Object> value = new TimeoutValueHolder<>(holder);
    Assertions.assertSame(holder, value.timeout(1), "Setters must return the holder");
    Assertions.assertTrue(value.getTimeoutValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getTimeout().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of timeout of smtp outbound config")
  void test_timeout_value_holder_assign_value_object() {
    Object holder = new Object();
    TimeoutValueHolder<Object> value = new TimeoutValueHolder<>(holder);
    TimeoutVO vo = TimeoutVO.from(1);
    Assertions.assertFalse(value.getTimeoutValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.timeout(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTimeoutValue().orElseThrow());
    Assertions.assertSame(holder, value.timeout(Optional.empty()));
    Assertions.assertFalse(value.getTimeoutValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.timeout(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTimeoutValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of timeout of smtp outbound config against the original")
  void test_timeout_value_holder_read() {
    Object holder = new Object();
    TimeoutValueHolder<Object> value = new TimeoutValueHolder<>(holder);
    TimeoutVO vo = TimeoutVO.from(1);
    TimeoutVO other = TimeoutVO.from(1);
    SmtpOutboundConfig original = Mockito.mock(SmtpOutboundConfig.class);
    Mockito.when(original.getTimeoutValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTimeout(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readTimeout(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.timeout(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTimeout(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTimeout(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of timeout of smtp outbound config")
  void test_timeout_value_holder_unset() {
    Object holder = new Object();
    TimeoutValueHolder<Object> value = new TimeoutValueHolder<>(holder);
    TimeoutVO vo = TimeoutVO.from(1);
    value.timeout(vo);
    Assertions.assertSame(holder, value.unsetTimeoutIfMatches("timeout_other"));
    Assertions.assertTrue(value.getTimeoutValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTimeoutIfMatches("timeout"));
    Assertions.assertFalse(value.getTimeoutValue().isPresent(),
        "The field name must clear the value");
    value.timeout(vo);
    Assertions.assertSame(holder, value.unsetTimeout());
    Assertions.assertFalse(value.getTimeoutValue().isPresent(), "Unset must clear the value");
  }
}
